 let rows=read(r.join("rows.json"));assert_eq!(rows.as_array().unwrap().len(),524);let mut cells=BTreeMap::<String,BTreeMap<String,Vec<(u64,f64)>>>::new();let mut calls=0;let mut latency=0;
 for row in rows.as_array().unwrap(){calls+=row["calls"].as_u64().unwrap()+3;if row["panel"]!="latency"{continue;}latency+=1;let samples=row["query_ns"].as_array().unwrap().iter().map(|v|v.as_f64().unwrap()).collect::<Vec<_>>();assert_eq!(samples.len(),17);let ms=median(&samples)/1e6;approx(ms,row["median_ms"].as_f64().unwrap());cells.entry(row["case"].as_str().unwrap().into()).or_default().entry(row["variant"].as_str().unwrap().into()).or_default().push((row["block"].as_u64().unwrap(),ms));}
 assert_eq!(calls,11712);assert_eq!(latency,496);let mut failed=BTreeSet::new();let mut ratios=BTreeMap::new();
 for(case,vars)in &mut cells{assert_eq!(vars.len(),4);for v in vars.values_mut(){v.sort_by_key(|x|x.0);assert_eq!(v.len(),31);for(i,x)in v.iter().enumerate(){assert_eq!(x.0,i as u64);}}
  for control in["OFF","FROZEN"]{let v=vars["ON"].iter().zip(&vars[control]).map(|(a,b)|a.1/b.1).collect::<Vec<_>>();let name=format!("{case}/ON/{control}");check(&a["pairs"][&name]["statistics"],&v);let(_,_,h,w)=stats(&v);let pass=if case=="1x2-w32"{h<1.&&w>=21}else{h<=1.02};assert_eq!(a["pairs"][&name]["passed"],pass);if !pass{failed.insert(name.clone());}ratios.insert(name,v);}
  let cal=vars["OFF"].iter().zip(&vars["FROZEN"]).map(|(a,b)|a.1/b.1).collect::<Vec<_>>();check(&a["calibration"][case]["statistics"],&cal);let(_,lo,hi,_)=stats(&cal);let pass=lo>=1./1.03&&hi<=1.03;assert_eq!(a["calibration"][case]["passed"],pass);if !pass{failed.insert(format!("{case}/OFF/FROZEN/calibration"));}
  let parent=vars["ON"].iter().zip(&vars["PARENT"]).map(|(a,b)|a.1/b.1).collect::<Vec<_>>();check(&a["parent_diagnostic_pairs"][case]["statistics"],&parent);
 }
 for control in["OFF","FROZEN"]{let v=(0..31).map(|i|((ratios[&format!("1x2-w32/ON/{control}")][i].ln()+ratios[&format!("2x2-w32/ON/{control}")][i].ln())/2.).exp()).collect::<Vec<_>>();check(&a["two_shape_aggregate"][control]["statistics"],&v);let(_,_,h,w)=stats(&v);let pass=h<1.&&w>=21;assert_eq!(a["two_shape_aggregate"][control]["passed"],pass);if !pass{failed.insert(format!("two_shapes/ON/{control}/gain"));}}
 assert_eq!(failed,a["failed_checks"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().to_string()).collect());assert_eq!(a["caller_gate"],failed.is_empty());
 let activation=read(r.join("activation.json"));let diag=activation["joint_top_observed_in_all_three_ON_profiles"]==true&&a["counters"].as_object().unwrap().values().all(|v|v["qualified"]==true)&&a["profiles"].as_object().unwrap().values().all(|v|v["attribution_qualified"]==true);assert_eq!(a["diagnostic_qualified"],diag);assert_eq!(a["eligible_for_SDK_stage"],failed.is_empty()&&diag);
 let mut archive_members=BTreeMap::new();for(name,base)in[("source.json.gz",r.join("source")),("receipts.json.gz",r.to_path_buf()),("helpers.json.gz",r.to_path_buf())]{let out=Command::new("gzip").arg("-dc").arg(d.join("artifacts").join(name)).output().unwrap();assert!(out.status.success());let data:Value=serde_json::from_slice(&out.stdout).unwrap();for(p,v)in data.as_object().unwrap(){assert!(!p.ends_with("-sdk")&&!p.ends_with(".b2q")&&!p.ends_with(".rlib")&&!p.ends_with(".data"));let bytes=if let Some(s)=v["utf8"].as_str(){s.as_bytes().to_vec()}else{v["hex"].as_str().unwrap().as_bytes().chunks_exact(2).map(|b|u8::from_str_radix(std::str::from_utf8(b).unwrap(),16).unwrap()).collect()};assert_eq!(digest(&bytes),v["sha256"]);assert_eq!(bytes.len(),v["bytes"].as_u64().unwrap()as usize);assert_eq!(bytes,fs::read(base.join(p)).unwrap());}archive_members.insert(name,data.as_object().unwrap().len());}assert_eq!(archive_members["source.json.gz"],176);
 let snapshot=read("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-30-current-bench-snapshot175/data.json");assert_eq!(read(d.join("artifacts/accepted-rows.json")),snapshot["rows"]);assert_eq!(snapshot["accepted_original8_CPU10x"],0);
