 let raw=fs::read_to_string(&saved).unwrap();let split=raw.find("\n\n").unwrap()+2;let mut note=format!("**{} at the complete-query stage.** Primary32 ON/OFF ratio is {:.6}; 2×2/32 is {:.6}. The two-shape aggregate and all control/calibration limits determine SDK eligibility; no full-proof speedup or adoption is claimed. [Independent review](artifacts/postcapture-review.json).\n\n",if failed.is_empty()&&diag{"Passed"}else{"Not qualified"},a["pairs"]["1x2-w32/ON/OFF"]["statistics"]["median"].as_f64().unwrap(),a["pairs"]["2x2-w32/ON/OFF"]["statistics"]["median"].as_f64().unwrap());
