 fs::write(d.join("README.md"),format!("{}{}{}",&raw[..split],note,&raw[split..])).unwrap();
 let mut link_targets=vec![];let text=fs::read_to_string(d.join("README.md")).unwrap();for s in text.split("](").skip(1){let target=s.split(')').next().unwrap();if target.starts_with("http")||target.starts_with('#'){continue;}link_targets.push(d.join(target));}let links=link_targets.len();
 let result=json!({"current_pins_verified":pins.as_object().unwrap().len(),"successful_commands_and_output_hashes":commands,"initial_compile_failure_retained":true,"latency_processes_independently_recomputed":latency,"queries_including_primes":calls,"all_paired_bounds_wins_and_aggregates_recomputed":true,"caller_gate":failed.is_empty(),"diagnostics":diag,"eligible_for_SDK_stage":failed.is_empty()&&diag,"parent_comparisons_diagnostic_only":true,"archive_members_byte_exact":archive_members,"all_nine_accepted_rows_unchanged":true,"original8_CPU10x":0,"proof_ledger":25231,"local_report_links":links,"publisher_helper_unchanged":true,"publisher_readme_sha256":hash(&saved),"review_source_sha256":hash(r.join("review.rs")),"no_native_test_or_capture_rerun":true});save(d.join("artifacts/postcapture-review.json"),&result);
 for path in link_targets{assert!(path.exists(),"{}",path.display());}let mut output=vec![];walk(d,&mut output);output.sort();fs::write(d.join("SHA256SUMS"),output.iter().filter(|p|p.file_name().unwrap()!="SHA256SUMS").map(|p|format!("{}  {}\n",hash(p),p.strip_prefix(d).unwrap().display())).collect::<String>()).unwrap();println!("Independent review: {commands} successful commands, {latency} latency processes, {calls} queries; gate{} diagnostics{}; no runtime rerun",failed.is_empty(),diag);
